$ cat > main.tf <<'EOF'
> resource "terraform_data" "ev_server" {
>   input            = "EV01"
>   triggers_replace = "v1"
> 
>   provisioner "local-exec" {
>     command = "echo 'server ${self.input} created' > ev01.txt"
>   }
> }
> 
> output "server_name" {
>   value = terraform_data.ev_server.output
> }
> EOF

$ cat > variables.tf <<'EOF'
> variable "environment" {
>   type        = string
>   description = "Which environment this is"
>   default     = "test"
> 
>   validation {
>     condition     = contains(["test", "prod"], var.environment)
>     error_message = "environment must be test or prod."
>   }
> }
> 
> variable "server_names" {
>   type    = list(string)
>   default = ["ev01", "sql01"]
> }
> 
> variable "db_password" {
>   type      = string
>   sensitive = true          # hidden in plan and output
>   default   = "demo-only-not-a-real-secret"
> }
> EOF

$ cat > main.tf <<'EOF'
> locals {
>   prefix = "${var.environment}-evault"
>   tags   = {
>     Env     = var.environment
>     Owner   = "ops-team"
>     Managed = "terraform"
>   }
>   instance_size = var.environment == "prod" ? "large" : "small"
> }
> 
> resource "terraform_data" "config" {
>   input = {
>     name  = local.prefix
>     size  = local.instance_size
>     tags  = local.tags
>     count = length(var.server_names)
>   }
> }
> 
> output "summary" {
>   value = "${local.prefix}: ${length(var.server_names)} servers, size ${local.instance_size}"
> }
> 
> output "db_password" {
>   value     = var.db_password
>   sensitive = true
> }
> EOF

$ cat > nginx.conf.tftpl <<'EOF'
> # generated for ${env}
> %{ for s in servers ~}
> upstream ${s} { server ${s}.corp.local:8080; }
> %{ endfor ~}
> EOF

$ cat > main.tf <<'EOF'
> variable "servers" {
>   type    = set(string)
>   default = ["ev01", "ev02", "sql01"]
> }
> 
> resource "terraform_data" "server" {
>   for_each = var.servers
>   input    = "${each.key}.corp.local"
> }
> 
> output "hosts" {
>   value = { for k, v in terraform_data.server : k => v.output }
> }
> EOF

$ cat > flag.tf <<'EOF'
> variable "enable_monitoring" {
>   type    = bool
>   default = false
> }
> 
> resource "terraform_data" "monitoring" {
>   count = var.enable_monitoring ? 1 : 0
>   input = "agent installed"
> }
> EOF

$ cat > deps.tf <<'EOF'
> resource "terraform_data" "network" {
>   input = "10.0.0.0/16"
> }
> 
> resource "terraform_data" "subnet" {
>   input = "subnet in ${terraform_data.network.output}"      # implicit dependency
> }
> 
> resource "terraform_data" "firewall" {
>   input      = "rules"
